package com.example.starter.domain;

/**
 * 干扰事件状态：OPEN 待初查；CONFIRMED 初查确认干扰、限功率中；REJECTED 初查排除干扰；CLOSED 结案。
 */
public enum EventStatus {
    OPEN,
    CONFIRMED,
    REJECTED,
    CLOSED
}

package com.example.starter.domain;

/**
 * 限功率指令状态：EXECUTING 执行中；SUPERSEDED 被更严格限值取代；RELEASED 已解除。
 */
public enum DirectiveStatus {
    EXECUTING,
    SUPERSEDED,
    RELEASED
}

package com.example.starter.domain;

/**
 * 初查结论：CONFIRMED_INTERFERENCE 确认干扰；NOT_INTERFERENCE 排除干扰。
 */
public enum ReviewConclusion {
    CONFIRMED_INTERFERENCE,
    NOT_INTERFERENCE
}

package com.example.starter.domain;

/**
 * 复测结果：NO_INTERFERENCE 无干扰；INTERFERENCE 仍有干扰。
 */
public enum RetestResult {
    NO_INTERFERENCE,
    INTERFERENCE
}

package com.example.starter.config;

import java.time.Clock;

import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

/**
 * 全局时钟：统一使用 UTC，测试中可替换为可控时钟以验证 24 小时督办等时间规则。
 */
@Configuration
public class ClockConfig {

    @Bean
    public Clock clock() {
        return Clock.systemUTC();
    }
}

package com.example.starter.error;

import org.springframework.http.HttpStatus;

/**
 * 业务规则异常：携带 HTTP 状态码，由全局异常处理器转换为错误响应。
 */
public class BusinessException extends RuntimeException {

    private final HttpStatus status;

    public BusinessException(HttpStatus status, String message) {
        super(message);
        this.status = status;
    }

    public HttpStatus status() {
        return status;
    }

    public static BusinessException unprocessable(String message) {
        return new BusinessException(HttpStatus.UNPROCESSABLE_ENTITY, message);
    }

    public static BusinessException notFound(String message) {
        return new BusinessException(HttpStatus.NOT_FOUND, message);
    }

    public static BusinessException conflict(String message) {
        return new BusinessException(HttpStatus.CONFLICT, message);
    }
}

