                "SELECT id FROM transmitter WHERE code = ?", Long.class, code);
        return id == null ? -1 : id;
    }

    protected int countRows(String table) {
        Integer count = jdbc.queryForObject("SELECT COUNT(*) FROM " + table, Integer.class);
        return count == null ? 0 : count;
    }
}

